// NewLimitWriter creates a writer that is limited to writing at most n
// bytes to w. This writer is not thread safe.
func NewLimitWriter(w io.Writer, n int64) io.Writer {
	return &limitWriter{
		w: w,
		n: n,
	}
}

// ErrMaximumWrite is returned when all bytes have been written.
var ErrMaximumWrite = errors.New("maximum write")

type limitWriter struct {
	w io.Writer
	n int64
}

func (w *limitWriter) Write(p []byte) (n int, err error) {
	if int64(len(p)) > w.n {
		p = p[:w.n]
	}
	if w.n > 0 {
		n, err = w.w.Write(p)
		w.n -= int64(n)
	}
	if w.n == 0 {
		err = ErrMaximumWrite
	}
	return
}
